#pragma once
#include <stdint.h>
// Declared in a header to make types visible to Arduino's autogenerated prototypes.
enum CmdType : uint8_t {
  SNAPSHOT_PATCH, APPLY_USER_PATCH, NOTE_ON, NOTE_OFF, ALL_OFF,
  BEND, PRESET, BENCH, MODE, SPLIT, POLY, CHORUS, REVERB,
  FILTER_MODE, CUTOFF, RESO, RING, SYNC, SELECT_LAYER, RESTORE, EDIT_PARAM, FILTER_DIAG, FILTER_ENV1_ROUTE, FILTER_RESO_AB
};
struct Cmd { CmdType type; uint8_t note; int32_t val; };
